#!/usr/bin/env npx ts-node
import * as fs from 'fs';
import * as path from 'path';
import * as csv from 'csv-parser';

// Base path for the S3 export data
const DATA_PATH = '/data/s3/foo-bar-prod-exports/initial-load/orders/2026-01/';
const MANIFEST_FILE = path.join(DATA_PATH, 'manifest.csv');
const INGEST_URL = 'http://localhost:4000/ingest/Orders';

interface ManifestRow {
  object_key: string;
  format: string;
  should_load: string;
  row_count: string;
}

interface OrderRecord {
  order_id: string;
  order_ts: string;
  customer_id: string;
  amount_cents: number;
  status: string;
  channel: string;
  country: string;
  promo_code?: string;
  source_object: string;
}

async function readManifest(): Promise<ManifestRow[]> {
  return new Promise((resolve, reject) => {
    const results: ManifestRow[] = [];
    fs.createReadStream(MANIFEST_FILE)
      .pipe(csv())
      .on('data', (data: ManifestRow) => results.push(data))
      .on('end', () => resolve(results))
      .on('error', reject);
  });
}

async function readCSVFile(filePath: string, sourceObject: string): Promise<OrderRecord[]> {
  return new Promise((resolve, reject) => {
    const results: OrderRecord[] = [];
    fs.createReadStream(filePath)
      .pipe(csv())
      .on('data', (data: any) => {
        const record: OrderRecord = {
          order_id: data.order_id,
          order_ts: data.order_ts,
          customer_id: data.customer_id,
          amount_cents: parseInt(data.amount_cents),
          status: data.status,
          channel: data.channel,
          country: data.country,
          promo_code: data.promo_code || undefined,
          source_object: sourceObject,
        };
        results.push(record);
      })
      .on('end', () => resolve(results))
      .on('error', reject);
  });
}

async function readJSONLFile(filePath: string, sourceObject: string): Promise<OrderRecord[]> {
  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.trim().split('\n');
  const results: OrderRecord[] = [];

  for (const line of lines) {
    if (line.trim()) {
      const data = JSON.parse(line);
      const record: OrderRecord = {
        order_id: data.order_id,
        order_ts: data.order_ts,
        customer_id: data.customer_id,
        amount_cents: data.amount_cents,
        status: data.status,
        channel: data.channel,
        country: data.country,
        promo_code: data.promo_code || undefined,
        source_object: sourceObject,
      };
      results.push(record);
    }
  }

  return results;
}

async function ingestRecord(record: OrderRecord): Promise<boolean> {
  try {
    const response = await fetch(INGEST_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(record),
    });

    if (!response.ok) {
      console.error(`Failed to ingest ${record.order_id}: ${response.status} ${response.statusText}`);
      return false;
    }

    return true;
  } catch (error) {
    console.error(`Error ingesting ${record.order_id}:`, error);
    return false;
  }
}

async function main() {
  console.log('Reading manifest...');
  const manifest = await readManifest();

  console.log(`Found ${manifest.length} entries in manifest`);

  // Filter for files that should be loaded
  const filesToLoad = manifest.filter(row => row.should_load === 'true');
  console.log(`Found ${filesToLoad.length} files to load:`);

  let totalRecordsLoaded = 0;
  let totalRecordsExpected = 0;

  for (const fileEntry of filesToLoad) {
    const filePath = path.join(DATA_PATH, fileEntry.object_key.replace('initial-load/orders/2026-01/', ''));
    const expectedCount = parseInt(fileEntry.row_count);
    totalRecordsExpected += expectedCount;

    console.log(`\nProcessing: ${fileEntry.object_key} (${fileEntry.format}, expecting ${expectedCount} records)`);

    let records: OrderRecord[] = [];

    try {
      if (fileEntry.format === 'csv') {
        records = await readCSVFile(filePath, fileEntry.object_key);
      } else if (fileEntry.format === 'jsonl') {
        records = await readJSONLFile(filePath, fileEntry.object_key);
      } else {
        console.error(`Unknown format: ${fileEntry.format}`);
        continue;
      }

      console.log(`Read ${records.length} records from file`);

      // Verify record count matches manifest
      if (records.length !== expectedCount) {
        console.warn(`Warning: Expected ${expectedCount} records but found ${records.length}`);
      }

      // Ingest each record
      let successCount = 0;
      for (const record of records) {
        const success = await ingestRecord(record);
        if (success) {
          successCount++;
        }
        // Small delay to avoid overwhelming the server
        await new Promise(resolve => setTimeout(resolve, 10));
      }

      console.log(`Successfully ingested ${successCount}/${records.length} records from ${fileEntry.object_key}`);
      totalRecordsLoaded += successCount;

    } catch (error) {
      console.error(`Error processing file ${filePath}:`, error);
    }
  }

  console.log(`\n=== SUMMARY ===`);
  console.log(`Total records expected: ${totalRecordsExpected}`);
  console.log(`Total records loaded: ${totalRecordsLoaded}`);
  console.log(`Files processed: ${filesToLoad.length}`);

  // Give the system a moment to process all records
  console.log('\nWaiting for processing to complete...');
  await new Promise(resolve => setTimeout(resolve, 2000));
}

